function build(fields){var shown={},items=[],sections={};fields.forEach(function(f){var n=f.getName(),g=f.constructor.name==="PDFCheckBox"&&groupName(n);if(g&&shown[g])return;if(g)shown[g]=true;items.push({name:n,group:g,node:g?makeGroup(g,fields.filter(function(x){return x.constructor.name==="PDFCheckBox"&&groupName(x.getName())===g})):makeField(f)})});items.sort(function(a,b){return orderFor(a.group||a.name)-orderFor(b.group||b.name)});items.forEach(function(item){var section=sectionFor(item.name,item.group);if(!sections[section]){var card=document.createElement("section"),heading=document.createElement("h2"),content=document.createElement("div");card.className="form-section";heading.textContent=section;content.className="section-fields";card.append(heading,content);area.appendChild(card);sections[section]=content}sections[section].appendChild(item.node)})}
